import type { Request, Response } from 'express';
// @ts-ignore -- Generated by pnpm build; local TS and JSON imports are bundled.
import app from '../build/api-app.mjs';

/** Current product metadata and HTML fallbacks for public routes that have no static page. */
export default function sitePage(req: Request, res: Response) {
  if (!['GET', 'HEAD'].includes(req.method || 'GET')) {
    res.setHeader('Allow', 'GET, HEAD');
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.statusCode = 405;
    res.end(JSON.stringify({ success: false, message: 'Method not allowed.' }));
    return;
  }
  const parameters = new URL(req.url || '/', 'http://localhost').searchParams;
  const value = (name: string): unknown => {
    const values = parameters.getAll(name);
    // Reject repeated routing parameters, including native requests without a query object.
    if (values.length > 1) return null;
    return req.query?.[name] ?? (values.length === 1 ? values[0] : undefined);
  };
  const slug = value('slug');
  const routePath = value('path');
  let target: string | undefined;
  if (slug !== undefined && routePath !== undefined) {
    // The rewrite selects exactly one routing mode; mixed parameters cannot override its page.
    target = undefined;
  } else if (slug !== undefined) {
    if (typeof slug === 'string' && /^[A-Za-z0-9_-]{1,121}$/.test(slug)) target = `/product/${encodeURIComponent(slug)}`;
  } else if (routePath === 'sitemap.xml') {
    target = '/sitemap.xml';
  } else if (typeof routePath === 'string' && /^[A-Za-z0-9/_-]{0,300}$/.test(routePath) && !routePath.includes('//')) {
    const path = `/${routePath.replace(/^\//, '')}`;
    // HTML routing must never become a second entrypoint into API or private files/assets.
    if (!/^\/(?:api|demos|assets|product-images)(?:\/|$)/i.test(path)) target = path;
  }
  if (!target) {
    res.setHeader('X-Robots-Tag', 'noindex');
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.statusCode = 404;
    res.end('Page not found.');
    return;
  }
  res.setHeader('Cache-Control', 'private, no-store');
  req.url = target;
  app(req, res);
}
